_ex = ['Client: home office that also works for guests. Needs: desk, sofa bed, storage; budget 1,500; style words: calm, warm, light.', 'Room 4.0 by 3.2 m: the diagonal should be 5.12 m; the client measures 5.10, so the plan is trusted within 2 cm.', 'Layout A puts the desk under the window and the sofa bed on the long wall with a 1.0 m path; layout B swaps them. The client picks A for light.', 'Palette: 60% soft neutral walls, 30% sofa and rug in warm grey, 10% accent cushions in terracotta, each with a reason.', "Budget 1,500: furniture 900, lighting 250, textiles 200, contingency 150; total within 3% of the client's limit.", 'The client prefers a smaller sofa; layout and list are updated and cost drops by 120.', 'The deck has four slides: brief, plan, mood board, list. The client decides in one call.', 'The handover checklist: paint, floor, furniture, lights, textiles, with safety notes for electrics.']
_extra = ['Ask the client to send photos from each corner in daylight.', 'Agree what the client will do and what you will do, in writing.', 'Mark sockets, radiators and windows on the plan.', 'Check door swings and clearances for every piece.', 'Collect samples of fabrics and finishes before final choice.', 'Consider noise, light and storage as well as looks.', 'Plan for people with different needs, including mobility.', 'Offer lower-cost options for each major item.', 'Keep a list of suppliers with delivery times.', 'Warn the client about any item that needs a professional.', 'Ask for feedback after the first presentation.', 'Set a limit on rounds of change, with a fair price after.', 'Ask for permission to use photos for your portfolio.', "Keep the client's address and photos private.", 'Write a short summary for the client to keep.', 'Write what you will change in your next project.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Map the remote process into steps with dates, such as brief call, measurements, concept board, revision and final plan, so the client knows what happens in week one.', 'Use one shared folder for photos and plans, and send a written summary after every call, which avoids confusion over decisions that were only made in conversation.'], ['Ask the client for their budget range, who uses the room, daily routines, favourite items to keep and a list of three things that currently annoy them.', 'Request photos of the room taken at morning and evening, since light changes colour and mood considerably across the day.'], ["Ask the client to measure each wall, window and door to the nearest centimetre, and to sketch a simple plan with the room's shape, then check that opposite walls add up sensibly.", 'Give clear photo instructions: stand in each corner at chest height, keep the camera level, and include the ceiling, floor and any radiators or sockets.'], ['Leave at least 90 centimetres for main walkways and about 45 centimetres between a sofa and coffee table, and draw each piece to scale before suggesting a layout.', 'Offer two layout options with a short reason for each, so the client can choose rather than simply accept or reject a single design.'], ["Build each concept board around a palette of three colours, one pattern and two textures, and note how each will look in the room's light.", 'Remind clients that colours on screens and in photos vary, and suggest ordering small samples and viewing them in the room for a full day.'], ['Prepare a sourcing sheet with item, supplier link, price, size, delivery time and an alternative, and total it against the budget, keeping a 10 percent contingency.', 'Check dimensions of each item against doors, stairs and lifts before recommending it, as a piece that cannot be delivered wastes money.'], ['Present designs in a short video call with a one-page summary, and invite comments on each element, writing the answers down so you can act on them.', 'Limit revisions to a stated number, such as two rounds, and explain what counts as a change of direction compared with a small adjustment.'], ['Hand over a final pack with the layout, shopping list, colour codes, care notes and an installation order, so the client can finish the project with confidence.', 'Ask for a testimonial and before-and-after photos with permission, and record what took longer than planned to improve your next quote.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

