_fix = {7: 'A guest-room handover pack lists the Wi-Fi code, rubbish days, a spare-key plan, and an emergency number on the fridge. The owner walks the host through it once and the host signs the list.'}
C['deep']['mods'] = [(m[0], _fix.get(i, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will lay out the remote consulting process in dated steps, so a client knows what happens each week and what you need from them.', 'You will run a brief conversation covering budget, daily routines, keepers and annoyances, helping you design for how the room is used and not only how it should look.', 'You will give clients precise measuring and photo instructions and cross-check the numbers, so your plans are accurate without ever visiting the room.', 'You will draw furniture to scale, respect walkway distances and offer two layouts with reasons, letting the client make an informed choice.', "You will build a three-colour, two-texture concept board and suggest sample testing at home, so the chosen mood still works in the room's real light.", 'You will assemble a sourcing sheet with totals, contingency and delivery checks, preventing purchases that exceed the budget or cannot fit through a door.', 'You will present options in a short call with a one-page summary and limit revision rounds, keeping decisions clear and the project moving forward.', 'You will deliver a final pack with layout, shopping list and installation order, then record what ran late, so clients finish confidently and your next quote improves.']
